/* selectMasterMpStBuyerCatlgStatsList */ SELECT 1 ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = XX.BUYER) AS BUYER_NM , XX.TARGET , XX.RESULT , ROUND(XX.RESULT/XX.TARGET*100,1) AS RESULT_RATE , XX.TARGET_01 , XX.RESULT_01 , DECODE(XX.TARGET_01,0,0,ROUND(XX.RESULT_01/XX.TARGET_01*100,1)) AS RESULT_RATE_01 , XX.TARGET_02 , XX.RESULT_02 , DECODE(XX.TARGET_02,0,0,ROUND(XX.RESULT_02/XX.TARGET_02*100,1)) AS RESULT_RATE_02 , XX.TARGET_03 , XX.RESULT_03 , DECODE(XX.TARGET_03,0,0,ROUND(XX.RESULT_03/XX.TARGET_03*100,1)) AS RESULT_RATE_03 , XX.TARGET_04 , XX.RESULT_04 , DECODE(XX.TARGET_04,0,0,ROUND(XX.RESULT_04/XX.TARGET_04*100,1)) AS RESULT_RATE_04 , XX.TARGET_05 , XX.RESULT_05 , DECODE(XX.TARGET_05,0,0,ROUND(XX.RESULT_05/XX.TARGET_05*100,1)) AS RESULT_RATE_05 , XX.TARGET_06 , XX.RESULT_06 , DECODE(XX.TARGET_06,0,0,ROUND(XX.RESULT_06/XX.TARGET_06*100,1)) AS RESULT_RATE_06 , XX.TARGET_07 , XX.RESULT_07 , DECODE(XX.TARGET_07,0,0,ROUND(XX.RESULT_07/XX.TARGET_07*100,1)) AS RESULT_RATE_07 , XX.TARGET_08 , XX.RESULT_08 , DECODE(XX.TARGET_08,0,0,ROUND(XX.RESULT_08/XX.TARGET_08*100,1)) AS RESULT_RATE_08 , XX.TARGET_09 , XX.RESULT_09 , DECODE(XX.TARGET_09,0,0,ROUND(XX.RESULT_09/XX.TARGET_09*100,1)) AS RESULT_RATE_09 , XX.TARGET_10 , XX.RESULT_10 , DECODE(XX.TARGET_10,0,0,ROUND(XX.RESULT_10/XX.TARGET_10*100,1)) AS RESULT_RATE_10 , XX.TARGET_11 , XX.RESULT_11 , DECODE(XX.TARGET_11,0,0,ROUND(XX.RESULT_11/XX.TARGET_11*100,1)) AS RESULT_RATE_11 , XX.TARGET_12 , XX.RESULT_12 , DECODE(XX.TARGET_12,0,0,ROUND(XX.RESULT_12/XX.TARGET_12*100,1)) AS RESULT_RATE_12 FROM ( SELECT X.BUYER , SUM(X.TARGET) AS TARGET , SUM(X.RESULT) AS RESULT , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'01',X.TARGET,0)) AS TARGET_01 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'01',X.RESULT,0)) AS RESULT_01 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'02',X.TARGET,0)) AS TARGET_02 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'02',X.RESULT,0)) AS RESULT_02 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'03',X.TARGET,0)) AS TARGET_03 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'03',X.RESULT,0)) AS RESULT_03 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'04',X.TARGET,0)) AS TARGET_04 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'04',X.RESULT,0)) AS RESULT_04 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'05',X.TARGET,0)) AS TARGET_05 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'05',X.RESULT,0)) AS RESULT_05 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'06',X.TARGET,0)) AS TARGET_06 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'06',X.RESULT,0)) AS RESULT_06 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'07',X.TARGET,0)) AS TARGET_07 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'07',X.RESULT,0)) AS RESULT_07 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'08',X.TARGET,0)) AS TARGET_08 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'08',X.RESULT,0)) AS RESULT_08 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'09',X.TARGET,0)) AS TARGET_09 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'09',X.RESULT,0)) AS RESULT_09 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'10',X.TARGET,0)) AS TARGET_10 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'10',X.RESULT,0)) AS RESULT_10 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'11',X.TARGET,0)) AS TARGET_11 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'11',X.RESULT,0)) AS RESULT_11 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'12',X.TARGET,0)) AS TARGET_12 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'12',X.RESULT,0)) AS RESULT_12 FROM ( SELECT HD.BUYER , SUBSTR(HD.ADD_DATE,0,6) AS ADD_MONTH ,(SELECT USR.DEPARTMENT FROM ICOMLUSR USR WHERE USR.USER_ID = HD.KEP_USER_ID) DEPARTMENT , HD.KEP_USER_ID , 1 TARGET , DECODE(HD.STATUS, 'C',1,0) RESULT FROM KEPCMSHD HD WHERE HD.STATUS != 'D' AND HD.ADD_DATE BETWEEN #{st_year}||'0101' AND #{st_year}||'1231' AND HD.BUYER != 'KRKEPB0004'
AND HD.JOB_TYPE = #{st_job_type}
) X GROUP BY X.BUYER ) XX UNION ALL SELECT 0 ,'전 체' AS BUYER_NM , XX.TARGET , XX.RESULT , ROUND(XX.RESULT/XX.TARGET*100,1) AS RESULT_RATE , XX.TARGET_01 , XX.RESULT_01 , DECODE(XX.TARGET_01,0,0,ROUND(XX.RESULT_01/XX.TARGET_01*100,1)) AS RESULT_RATE_01 , XX.TARGET_02 , XX.RESULT_02 , DECODE(XX.TARGET_02,0,0,ROUND(XX.RESULT_02/XX.TARGET_02*100,1)) AS RESULT_RATE_02 , XX.TARGET_03 , XX.RESULT_03 , DECODE(XX.TARGET_03,0,0,ROUND(XX.RESULT_03/XX.TARGET_03*100,1)) AS RESULT_RATE_03 , XX.TARGET_04 , XX.RESULT_04 , DECODE(XX.TARGET_04,0,0,ROUND(XX.RESULT_04/XX.TARGET_04*100,1)) AS RESULT_RATE_04 , XX.TARGET_05 , XX.RESULT_05 , DECODE(XX.TARGET_05,0,0,ROUND(XX.RESULT_05/XX.TARGET_05*100,1)) AS RESULT_RATE_05 , XX.TARGET_06 , XX.RESULT_06 , DECODE(XX.TARGET_06,0,0,ROUND(XX.RESULT_06/XX.TARGET_06*100,1)) AS RESULT_RATE_06 , XX.TARGET_07 , XX.RESULT_07 , DECODE(XX.TARGET_07,0,0,ROUND(XX.RESULT_07/XX.TARGET_07*100,1)) AS RESULT_RATE_07 , XX.TARGET_08 , XX.RESULT_08 , DECODE(XX.TARGET_08,0,0,ROUND(XX.RESULT_08/XX.TARGET_08*100,1)) AS RESULT_RATE_08 , XX.TARGET_09 , XX.RESULT_09 , DECODE(XX.TARGET_09,0,0,ROUND(XX.RESULT_09/XX.TARGET_09*100,1)) AS RESULT_RATE_09 , XX.TARGET_10 , XX.RESULT_10 , DECODE(XX.TARGET_10,0,0,ROUND(XX.RESULT_10/XX.TARGET_10*100,1)) AS RESULT_RATE_10 , XX.TARGET_11 , XX.RESULT_11 , DECODE(XX.TARGET_11,0,0,ROUND(XX.RESULT_11/XX.TARGET_11*100,1)) AS RESULT_RATE_11 , XX.TARGET_12 , XX.RESULT_12 , DECODE(XX.TARGET_12,0,0,ROUND(XX.RESULT_12/XX.TARGET_12*100,1)) AS RESULT_RATE_12 FROM ( SELECT SUM(X.TARGET) AS TARGET , SUM(X.RESULT) AS RESULT , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'01',X.TARGET,0)) AS TARGET_01 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'01',X.RESULT,0)) AS RESULT_01 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'02',X.TARGET,0)) AS TARGET_02 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'02',X.RESULT,0)) AS RESULT_02 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'03',X.TARGET,0)) AS TARGET_03 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'03',X.RESULT,0)) AS RESULT_03 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'04',X.TARGET,0)) AS TARGET_04 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'04',X.RESULT,0)) AS RESULT_04 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'05',X.TARGET,0)) AS TARGET_05 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'05',X.RESULT,0)) AS RESULT_05 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'06',X.TARGET,0)) AS TARGET_06 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'06',X.RESULT,0)) AS RESULT_06 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'07',X.TARGET,0)) AS TARGET_07 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'07',X.RESULT,0)) AS RESULT_07 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'08',X.TARGET,0)) AS TARGET_08 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'08',X.RESULT,0)) AS RESULT_08 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'09',X.TARGET,0)) AS TARGET_09 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'09',X.RESULT,0)) AS RESULT_09 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'10',X.TARGET,0)) AS TARGET_10 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'10',X.RESULT,0)) AS RESULT_10 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'11',X.TARGET,0)) AS TARGET_11 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'11',X.RESULT,0)) AS RESULT_11 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'12',X.TARGET,0)) AS TARGET_12 , SUM(DECODE(SUBSTR(X.ADD_MONTH,5,2),'12',X.RESULT,0)) AS RESULT_12 FROM ( SELECT SUBSTR(HD.ADD_DATE,0,6) AS ADD_MONTH ,(SELECT USR.DEPARTMENT FROM ICOMLUSR USR WHERE USR.USER_ID = HD.KEP_USER_ID) DEPARTMENT , HD.KEP_USER_ID , 1 TARGET , DECODE(HD.STATUS, 'C',1,0) RESULT FROM KEPCMSHD HD WHERE HD.STATUS != 'D' AND HD.ADD_DATE BETWEEN #{st_year}||'0101' AND #{st_year}||'1231' AND HD.BUYER != 'KRKEPB0004'
AND HD.JOB_TYPE = #{st_job_type}
) X ) XX ORDER BY 1,2
